/// An overlay (docs/spec.md §3.4.8): the entries written over an unchanged view.
pub struct Ov<'a, K, V> {
    b: &'a dyn Get<K, V>,
    m: BTreeMap<K, V>,
}

impl<'a, K: Ord, V: Clone> Ov<'a, K, V> {
    pub fn over(b: &'a dyn Get<K, V>) -> Self {
        Ov { b, m: BTreeMap::new() }
    }
    pub fn writes(self) -> BTreeMap<K, V> {
        self.m
    }
}

impl<K: Ord, V: Clone> Get<K, V> for Ov<'_, K, V> {
    fn get(&self, k: &K) -> V {
        match self.m.get(k) {
            Some(v) => v.clone(),
            None => self.b.get(k),
        }
    }
    fn get_ref(&self, k: &K) -> &V {
        match self.m.get(k) {
            Some(v) => v,
            None => self.b.get_ref(k),
        }
    }
}

impl<K: Ord, V: Clone> GetSet<K, V> for Ov<'_, K, V> {
    fn set(&mut self, k: K, v: V) {
        self.m.insert(k, v);
    }
    fn as_get(&self) -> &dyn Get<K, V> {
        self
    }
    fn slot(&mut self, k: K) -> &mut V {
        let b = self.b;
        self.m.entry(k).or_insert_with_key(|k| b.get(k))
    }
}

/// A per-id growing list (docs/spec.md §3.10.3, repr adj-append): one pool of
/// (value, next) cells shared by the ids, a free list of the cells released, and
/// per id its first cell, last cell and length. An append, a drain (tail), head,
/// `== []` and `#` cost O(1); a copy or a write of a whole list O(k).
#[derive(Debug, Clone)]
pub struct Adj<X> {
    /// The list of an id never written.
    d: Vec<X>,
    val: Vec<X>,
    next: Vec<u32>,
    free: u32,
    /// Per id (first cell, last cell, length), in pages of PAGE ids: an id whose list is
    /// the default again has none, and a page with no id left is freed.
    ids: Vec<Option<Box<Page<Option<(u32, u32, u32)>>>>>,
}

/// A write of a per-id growing list, applied after the summand's reads (§3.8.4).
pub enum AdjOp<X> {
    Set(u32, Vec<X>),
    Push(u32, X),
    Pop(u32),
}

impl<X> AdjOp<X> {
    /// The id it writes.
    pub fn id(&self) -> u32 {
        match self {
            AdjOp::Set(i, _) | AdjOp::Push(i, _) | AdjOp::Pop(i) => *i,
        }
    }
}

const ADJ_NIL: u32 = u32::MAX;

/// A cell or id as an index; u32 always fits a usize where the crate builds.
fn adj_at(c: u32) -> usize {
    usize::try_from(c).unwrap_or(usize::MAX)
}

impl<X: Clone + PartialEq> Adj<X> {
    pub fn new(d: Vec<X>) -> Adj<X> {
        Adj { d, val: Vec::new(), next: Vec::new(), free: ADJ_NIL, ids: Vec::new() }
    }

    fn slot(&self, i: u32) -> Option<(u32, u32, u32)> {
        let k = adj_at(i);
        match self.ids.get(k / PAGE) {
            Some(Some(page)) => page.e.get(k % PAGE).copied().flatten(),
            _ => None,
        }
    }

    fn link(&self, c: u32) -> u32 {
        self.next.get(adj_at(c)).copied().unwrap_or(ADJ_NIL)
    }

    fn set_link(&mut self, c: u32, n: u32) {
        if let Some(l) = self.next.get_mut(adj_at(c)) {
            *l = n;
        }
    }

    /// A cell holding x, from the free list or new.
    fn alloc(&mut self, x: X) -> Result<u32, StepError> {
        let c = self.free;
        if let Some(v) = self.val.get_mut(adj_at(c)) {
            *v = x;
            self.free = self.link(c);
            self.set_link(c, ADJ_NIL);
            return Ok(c);
        }
        let c = u32::try_from(self.val.len()).ok().filter(|c| *c != ADJ_NIL).ok_or(StepError::Overflow("pool"))?;
        self.val.push(x);
        self.next.push(ADJ_NIL);
        Ok(c)
    }

    /// The cells from c on go to the free list.
    fn release(&mut self, mut c: u32) {
        while c != ADJ_NIL {
            let n = self.link(c);
            self.set_link(c, self.free);
            self.free = c;
            c = n;
        }
    }

    /// Id i's slot set to s, or cleared when s is an empty list and the default is empty.
    fn put(&mut self, i: u32, s: (u32, u32, u32)) {
        let k = adj_at(i);
        let (q, o) = (k / PAGE, k % PAGE);
        let now = if s.2 == 0 && self.d.is_empty() { None } else { Some(s) };
        if now.is_none() && !matches!(self.ids.get(q), Some(Some(_))) {
            return;
        }
        if self.ids.len() <= q {
            self.ids.resize_with(q.saturating_add(1), || None);
        }
        if let Some(slot) = self.ids.get_mut(q) {
            let page = slot.get_or_insert_with(|| Box::new(Page { n: 0, e: vec![None; PAGE] }));
            if let Some(x) = page.e.get_mut(o) {
                match (x.is_some(), now.is_some()) {
                    (false, true) => page.n = page.n.saturating_add(1),
                    (true, false) => page.n = page.n.saturating_sub(1),
                    _ => {}
                }
                *x = now;
            }
            if page.n == 0 {
                *slot = None;
            }
        }
    }

    /// The slot of id i, with the default list put into the pool if i was never written.
    fn own(&mut self, i: u32) -> Result<(u32, u32, u32), StepError> {
        if let Some(s) = self.slot(i) {
            return Ok(s);
        }
        self.put(i, (ADJ_NIL, ADJ_NIL, 0));
        for x in self.d.clone() {
            self.push(i, x)?;
        }
        Ok(self.slot(i).unwrap_or((ADJ_NIL, ADJ_NIL, 0)))
    }

    pub fn to_vec(&self, i: u32) -> Vec<X> {
        let Some((mut c, _, _)) = self.slot(i) else { return self.d.clone() };
        let mut out = Vec::new();
        while let Some(x) = self.val.get(adj_at(c)) {
            out.push(x.clone());
            c = self.link(c);
        }
        out
    }

    pub fn head(&self, i: u32) -> Result<X, StepError> {
        match self.slot(i) {
            None => self.d.first().cloned(),
            Some((c, _, _)) => self.val.get(adj_at(c)).cloned(),
        }
        .ok_or(StepError::Undefined("head"))
    }

    pub fn len(&self, i: u32) -> usize {
        self.slot(i).map_or(self.d.len(), |(_, _, n)| adj_at(n))
    }

    pub fn is_empty(&self, i: u32) -> bool {
        self.len(i) == 0
    }

    /// f[i -> f(i) <| x].
    pub fn push(&mut self, i: u32, x: X) -> Result<(), StepError> {
        let (first, last, n) = self.own(i)?;
        let c = self.alloc(x)?;
        let n = n.checked_add(1).ok_or(StepError::Overflow("pool"))?;
        if last == ADJ_NIL {
            self.put(i, (c, c, n));
        } else {
            self.set_link(last, c);
            self.put(i, (first, c, n));
        }
        Ok(())
    }

    /// f[i -> tail(f(i))].
    pub fn pop(&mut self, i: u32) -> Result<(), StepError> {
        let (first, last, n) = self.own(i)?;
        if n == 0 {
            return Err(StepError::Undefined("tail"));
        }
        let next = self.link(first);
        self.set_link(first, self.free);
        self.free = first;
        self.put(i, if next == ADJ_NIL { (ADJ_NIL, ADJ_NIL, 0) } else { (next, last, n.saturating_sub(1)) });
        Ok(())
    }

    /// f[i -> l].
    pub fn set(&mut self, i: u32, l: Vec<X>) -> Result<(), StepError> {
        if let Some((first, _, _)) = self.slot(i) {
            self.release(first);
        }
        self.put(i, (ADJ_NIL, ADJ_NIL, 0));
        for x in l {
            self.push(i, x)?;
        }
        Ok(())
    }

    pub fn apply(&mut self, op: AdjOp<X>) -> Result<(), StepError> {
        match op {
            AdjOp::Set(i, l) => self.set(i, l),
            AdjOp::Push(i, x) => self.push(i, x),
            AdjOp::Pop(i) => self.pop(i),
        }
    }

    /// The pages of ids holding a list that differs from the default (for the memory a run keeps).
    pub fn pages(&self) -> usize {
        self.ids.iter().filter(|x| x.is_some()).count()
    }

    /// The ids whose list differs from the default, ascending, with their lists.
    pub fn entries(&self) -> Vec<(u32, Vec<X>)> {
        (0..self.ids.len().saturating_mul(PAGE))
            .filter_map(|k| u32::try_from(k).ok())
            .map(|i| (i, self.to_vec(i)))
            .filter(|(i, l)| self.slot(*i).is_some() && *l != self.d)
            .collect()
    }
}

mod rt {
    use super::StepError;
    use std::collections::BTreeSet;

    pub fn add(a: i128, b: i128) -> Result<i128, StepError> {
        a.checked_add(b).ok_or(StepError::Overflow("+"))
    }
    pub fn sub(a: i128, b: i128) -> Result<i128, StepError> {
        a.checked_sub(b).ok_or(StepError::Overflow("-"))
    }
    pub fn mul(a: i128, b: i128) -> Result<i128, StepError> {
        a.checked_mul(b).ok_or(StepError::Overflow("*"))
    }
    pub fn div(a: i128, b: i128) -> Result<i128, StepError> {
        a.checked_div_euclid(b).ok_or(StepError::Undefined("div"))
    }
    pub fn md(a: i128, b: i128) -> Result<i128, StepError> {
        a.checked_rem_euclid(b).ok_or(StepError::Undefined("mod"))
    }
    pub fn neg(a: i128) -> Result<i128, StepError> {
        a.checked_neg().ok_or(StepError::Overflow("-"))
    }
    /// a ∸ b: max(0, a - b) (docs/spec.md §3.2.6).
    pub fn monus(a: i128, b: i128) -> Result<i128, StepError> {
        Ok(sub(a, b)?.max(0))
    }
    /// A value written to a parameter fits its width (docs/spec.md §3.12.4).
    pub fn fit(v: i128, lo: i128, hi: i128, name: &'static str) -> Result<i128, StepError> {
        if v < lo || v > hi { Err(StepError::Overflow(name)) } else { Ok(v) }
    }
    pub fn int2nat(a: i128) -> Result<i128, StepError> {
        if a < 0 { Err(StepError::Undefined("Int2Nat")) } else { Ok(a) }
    }
    pub fn nat2pos(a: i128) -> Result<i128, StepError> {
        if a <= 0 { Err(StepError::Undefined("Nat2Pos")) } else { Ok(a) }
    }
    pub fn id(a: i128) -> Result<u32, StepError> {
        u32::try_from(a).map_err(|_| StepError::Overflow("id"))
    }
    pub fn count(n: usize) -> Result<i128, StepError> {
        i128::try_from(n).map_err(|_| StepError::Overflow("#"))
    }
    pub fn cons<X>(x: X, mut l: Vec<X>) -> Vec<X> {
        l.insert(0, x);
        l
    }
    pub fn snoc<X>(mut l: Vec<X>, x: X) -> Vec<X> {
        l.push(x);
        l
    }
    pub fn cat<X>(mut a: Vec<X>, b: Vec<X>) -> Vec<X> {
        a.extend(b);
        a
    }
    /// The head of a list read in place: one element cloned, not the list.
    pub fn head_ref<X: Clone>(l: &[X]) -> Result<X, StepError> {
        l.first().cloned().ok_or(StepError::Undefined("head"))
    }
    /// The head of a queue parameter (repr deque).
    pub fn dq_head<X: Clone>(l: &std::collections::VecDeque<X>) -> Result<X, StepError> {
        l.front().cloned().ok_or(StepError::Undefined("head"))
    }
    pub fn head<X>(l: Vec<X>) -> Result<X, StepError> {
        l.into_iter().next().ok_or(StepError::Undefined("head"))
    }
    pub fn tail<X>(mut l: Vec<X>) -> Result<Vec<X>, StepError> {
        if l.is_empty() {
            return Err(StepError::Undefined("tail"));
        }
        l.remove(0);
        Ok(l)
    }
    pub fn rhead<X>(mut l: Vec<X>) -> Result<X, StepError> {
        l.pop().ok_or(StepError::Undefined("rhead"))
    }
    pub fn rtail<X>(mut l: Vec<X>) -> Result<Vec<X>, StepError> {
        if l.pop().is_none() {
            return Err(StepError::Undefined("rtail"));
        }
        Ok(l)
    }
    pub fn at<X>(l: Vec<X>, i: i128) -> Result<X, StepError> {
        let i = usize::try_from(i).map_err(|_| StepError::Undefined("."))?;
        l.into_iter().nth(i).ok_or(StepError::Undefined("."))
    }
    pub fn nth<X: Clone>(l: &[X], i: usize) -> Result<X, StepError> {
        l.get(i).cloned().ok_or(StepError::Undefined("walk"))
    }
    pub fn rest<X: Clone>(l: &[X], i: usize) -> Vec<X> {
        l.get(i.saturating_add(1)..).map(<[X]>::to_vec).unwrap_or_default()
    }
    // The set operations update the larger operand in place: the cost is that of the
    // smaller one, never a copy of the set (docs/spec.md §3.13.1).
    pub fn union<X: Ord>(mut a: BTreeSet<X>, mut b: BTreeSet<X>) -> BTreeSet<X> {
        if a.len() < b.len() {
            std::mem::swap(&mut a, &mut b);
        }
        a.extend(b);
        a
    }
    pub fn diff<X: Ord>(mut a: BTreeSet<X>, b: BTreeSet<X>) -> BTreeSet<X> {
        if b.len() <= a.len() {
            for x in &b {
                a.remove(x);
            }
        } else {
            a.retain(|x| !b.contains(x));
        }
        a
    }
    pub fn inter<X: Ord>(mut a: BTreeSet<X>, mut b: BTreeSet<X>) -> BTreeSet<X> {
        if b.len() < a.len() {
            std::mem::swap(&mut a, &mut b);
        }
        a.retain(|x| b.contains(x));
        a
    }
    pub fn insert<X: Ord>(mut s: BTreeSet<X>, x: X) -> BTreeSet<X> {
        s.insert(x);
        s
    }
    /// least(W) (docs/spec.md §3.7.6).
    pub fn least<X: Ord + Clone>(s: &BTreeSet<X>) -> Result<X, StepError> {
        s.first().cloned().ok_or(StepError::Undefined("least of an empty set"))
    }
    /// An ordered insert into a list sorted by id (docs/spec.md §3.10.6): the
    /// model's walk, at the place a binary search finds.
    pub fn ins_sorted<X: Ord>(l: &mut Vec<X>, u: X) {
        if let Err(p) = l.binary_search(&u) {
            l.insert(p, u);
        }
    }
    /// An insert ordered by a key, into a list kept sorted by that key (docs/spec.md
    /// §3.10.7): the model's walk puts u before the first element whose key is greater,
    /// the place a binary search finds.
    pub fn ins_by_key<X, K: Ord>(l: &mut Vec<X>, u: X, key: impl Fn(&X) -> K) {
        let ku = key(&u);
        let p = l.partition_point(|x| key(x) <= ku);
        l.insert(p, u);
    }
    /// tail of a list entry, in place.
    pub fn pop_first<X>(l: &mut Vec<X>) -> Result<(), StepError> {
        if l.is_empty() {
            return Err(StepError::Undefined("tail"));
        }
        l.remove(0);
        Ok(())
    }
    /// The removal of u's first occurrence, in place.
    pub fn rem_first<X: PartialEq>(l: &mut Vec<X>, u: &X) {
        if let Some(p) = l.iter().position(|x| x == u) {
            l.remove(p);
        }
    }
    /// tail(l) == [], read in place.
    pub fn tail_empty<X>(l: &[X]) -> Result<bool, StepError> {
        if l.is_empty() {
            return Err(StepError::Undefined("tail"));
        }
        Ok(l.len() == 1)
    }
    /// l with u's first occurrence removed == [], read in place.
    pub fn rem_empty<X: PartialEq>(l: &[X], u: &X) -> bool {
        l.is_empty() || (l.len() == 1 && l.first() == Some(u))
    }
}

/// A malformed entry (docs/spec.md §3.14.2).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodeError(pub &'static str);

mod codec {
    use super::DecodeError;

    pub fn nat(v: i128, out: &mut Vec<u8>) {
        // A Nat is never negative; 0 stands in for what cannot happen.
        let mut x = u128::try_from(v).unwrap_or(0);
        loop {
            let b = u8::try_from(x & 0x7F).unwrap_or(0);
            x >>= 7;
            if x == 0 {
                out.push(b);
                return;
            }
            out.push(b | 0x80);
        }
    }
    pub fn int(v: i128, out: &mut Vec<u8>) {
        // zigzag: 0, -1, 1, -2, ... as 0, 1, 2, 3, ...
        let z = if v >= 0 { u128::try_from(v).unwrap_or(0) << 1 } else { (v.unsigned_abs().saturating_sub(1) << 1) | 1 };
        let mut x = z;
        loop {
            let b = u8::try_from(x & 0x7F).unwrap_or(0);
            x >>= 7;
            if x == 0 {
                out.push(b);
                return;
            }
            out.push(b | 0x80);
        }
    }
    pub fn boolean(v: bool, out: &mut Vec<u8>) {
        out.push(u8::from(v));
    }
    pub fn len(n: usize, out: &mut Vec<u8>) {
        nat(i128::try_from(n).unwrap_or(0), out);
    }

    pub struct Rd<'a> {
        pub b: &'a [u8],
        pub p: usize,
    }

    impl Rd<'_> {
        pub fn byte(&mut self) -> Result<u8, DecodeError> {
            let v = *self.b.get(self.p).ok_or(DecodeError("end of entry"))?;
            self.p = self.p.saturating_add(1);
            Ok(v)
        }
        fn raw(&mut self) -> Result<u128, DecodeError> {
            let mut x: u128 = 0;
            let mut sh: u32 = 0;
            loop {
                let b = self.byte()?;
                if sh > 126 {
                    return Err(DecodeError("a number too long"));
                }
                x |= u128::from(b & 0x7F) << sh;
                sh = sh.saturating_add(7);
                if b & 0x80 == 0 {
                    return Ok(x);
                }
            }
        }
        pub fn nat(&mut self) -> Result<i128, DecodeError> {
            i128::try_from(self.raw()?).map_err(|_| DecodeError("a number out of range"))
        }
        pub fn int(&mut self) -> Result<i128, DecodeError> {
            let z = self.raw()?;
            let m = i128::try_from(z >> 1).map_err(|_| DecodeError("a number out of range"))?;
            Ok(if z & 1 == 0 { m } else { m.checked_neg().and_then(|x| x.checked_sub(1)).ok_or(DecodeError("a number out of range"))? })
        }
        pub fn boolean(&mut self) -> Result<bool, DecodeError> {
            match self.byte()? {
                0 => Ok(false),
                1 => Ok(true),
                _ => Err(DecodeError("a Bool")),
            }
        }
        pub fn len(&mut self) -> Result<usize, DecodeError> {
            usize::try_from(self.nat()?).map_err(|_| DecodeError("a length"))
        }
        pub fn done(&self) -> bool {
            self.p == self.b.len()
        }
    }
}

/// A value printed as mCRL2 prints it (for the tests that compare with mCRL2).
pub trait M2 {
    fn m2(&self, out: &mut String);
}

impl M2 for i128 {
    fn m2(&self, out: &mut String) {
        out.push_str(&self.to_string());
    }
}

impl M2 for bool {
    fn m2(&self, out: &mut String) {
        out.push_str(if *self { "true" } else { "false" });
    }
}

impl<X: M2> M2 for Vec<X> {
    fn m2(&self, out: &mut String) {
        out.push('[');
        for (k, x) in self.iter().enumerate() {
            if k > 0 {
                out.push_str(", ");
            }
            x.m2(out);
        }
        out.push(']');
    }
}

impl<X: M2> M2 for BTreeSet<X> {
    fn m2(&self, out: &mut String) {
        out.push('{');
        for (k, x) in self.iter().enumerate() {
            if k > 0 {
                out.push_str(", ");
            }
            x.m2(out);
        }
        out.push('}');
    }
}

impl FunKey for TSt {}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Default, Copy)]
pub enum TSt {
    #[default]
    ABSENT,
    WAITING,
    READY,
    RUNNING,
    DONE,
    FAILED,
}

impl M2 for TSt {
    fn m2(&self, out: &mut String) {
        out.push_str(match self {
            TSt::ABSENT => "ABSENT",
            TSt::WAITING => "WAITING",
            TSt::READY => "READY",
            TSt::RUNNING => "RUNNING",
            TSt::DONE => "DONE",
            TSt::FAILED => "FAILED",
        });
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Default, Copy)]
pub struct Task(pub u32);

impl FunKey for Task {
    fn dense(&self) -> Option<usize> {
        usize::try_from(self.0).ok()
    }
    fn undense(i: usize) -> Option<Self> {
        u32::try_from(i).ok().map(Task)
    }
}

impl M2 for Task {
    fn m2(&self, out: &mut String) {
        out.push_str("task(");
        out.push_str(&self.0.to_string());
        out.push(')');
    }
}

pub fn m_adduser(a0: &Vec<Task>, a1: Task, a2: &mut dyn GetSet<Task, Vec<Task>>) -> Result<(), StepError> {
    let v_l = a0;
    let mut v_t = a1;
    let v_u = a2;
    let mut i: usize = 0;
    let n = v_l.len();
    let r: () = loop {
        if i == n {
            let mut wr: Vec<_> = Vec::new();
            for (k, v) in wr {
                v_u.set(k, v);
            }
            break ();
        }
        let x = rt::nth(&v_l, i)?;
        let mut wc1: Vec<_> = Vec::new();
        wc1.push((x.clone(), rt::snoc((v_u.as_get()).get(&x.clone()), v_t.clone())));
        for (k, v) in wc1 {
            v_u.set(k, v);
        }
        i = i.saturating_add(1);
        continue;
    };
    Ok(r)
}

pub fn m_below(a0: &Vec<Task>, a1: i128) -> Result<bool, StepError> {
    let v_l = a0;
    let mut v_n = a1;
    let mut i: usize = 0;
    let n = v_l.len();
    let r: bool = loop {
        if i == n {
            break true;
        }
        let x = rt::nth(&v_l, i)?;
        if !((i128::from((x.clone()).0) < v_n.clone())) {
            break false;
        }
        i = i.saturating_add(1);
        continue;
    };
    Ok(r)
}

pub fn m_gen_init_free(a0: i128) -> Result<i128, StepError> {
    Ok(a0.clone())
}

/// The configuration parameters of Core (§3.6.2).
#[derive(Debug, Clone)]
pub struct Config {
    pub w: i128,
}

/// A state of Core: one field per parameter.
#[derive(Debug, Clone)]
pub struct S {
    pub w: i128,
    pub nt: i128,
    pub begun: bool,
    pub ended: bool,
    pub free: i128,
    pub pending: i128,
    pub settled: i128,
    pub st: Fun<Task, TSt>,
    pub kids: Fun<Task, Vec<Task>>,
    pub isgoal: Fun<Task, bool>,
    pub told: Fun<Task, bool>,
    pub users: Fun<Task, Vec<Task>>,
    pub missing: Fun<Task, i128>,
    pub broken: Fun<Task, bool>,
    pub todo: Fun<Task, Vec<Task>>,
    pub dirty_Task: Vec<u32>,
    pub ix_due: Ix<i128>,
    pub ix_doomed: Ix<i128>,
    pub ix_telling: Ix<i128>,
    pub ix_runnable: Ix<i128>,
    pub ix_queued: Ix<i128>,
}

fn initial(config: &Config) -> Result<S, StepError> {
    Ok(S {
        w: rt::fit(config.w.clone(), 0, 4294967295, "w")?,
        nt: rt::fit(0i128, 0, 4294967295, "nt")?,
        begun: false,
        ended: false,
        free: rt::fit(m_gen_init_free(config.w.clone())?, 0, 4294967295, "free")?,
        pending: rt::fit(0i128, 0, 4294967295, "pending")?,
        settled: rt::fit(0i128, 0, 4294967295, "settled")?,
        st: Fun::new(TSt::ABSENT),
        kids: Fun::new(Vec::new()),
        isgoal: Fun::new(false),
        told: Fun::new(false),
        users: Fun::new(Vec::new()),
        missing: Fun::new(0i128),
        broken: Fun::new(false),
        todo: Fun::new(Vec::new()),
        dirty_Task: Default::default(),
        ix_due: Default::default(),
        ix_doomed: Default::default(),
        ix_telling: Default::default(),
        ix_runnable: Default::default(),
        ix_queued: Default::default(),
    })
}

