// c_define
fn match0(s: &S, a0: &Task, a1: &Vec<Task>) -> Result<Option<(Task, Vec<Task>, )>, StepError> {
    let v_t = a0.clone();
    let v_ks = a1.clone();
    if !(((!s.begun.clone()) && ((i128::from((v_t.clone()).0) == s.nt.clone()) && m_below(&v_ks, s.nt.clone())?))) {
        return Ok(None);
    }
    Ok(Some((v_t, v_ks, )))
}

fn fire0(s: &mut S, env: (Task, Vec<Task>, )) -> Result<(), StepError> {
    let (v_t, v_ks, ) = env;
    let n_nt = rt::add(s.nt.clone(), 1i128)?;
    let mut o_st = Ov::over(&s.st);
    o_st.set(v_t.clone(), TSt::WAITING);
    let w_st = o_st.writes();
    let mut o_kids = Ov::over(&s.kids);
    o_kids.set(v_t.clone(), v_ks.clone());
    let w_kids = o_kids.writes();
    let mut o_users = Ov::over(&s.users);
    m_adduser(&v_ks, v_t.clone(), &mut o_users)?;
    let w_users = o_users.writes();
    let mut o_missing = Ov::over(&s.missing);
    o_missing.set(v_t.clone(), rt::count((v_ks).len())?);
    let w_missing = o_missing.writes();
    for (k, v) in w_st {
        s.st.set(k, v);
    }
    for (k, v) in w_kids {
        s.kids.set(k, v);
    }
    for (k, v) in w_users {
        s.users.set(k, v);
    }
    for (k, v) in w_missing {
        s.missing.set(k, rt::fit(v, 0, 4294967295, "missing")?);
    }
    s.nt = rt::fit(n_nt, 0, 4294967295, "nt")?;
    Ok(())
}

// c_goal
fn match1(s: &S, a0: &Task) -> Result<Option<(Task, )>, StepError> {
    let v_t = a0.clone();
    if !(((!s.begun.clone()) && ((i128::from((v_t.clone()).0) < s.nt.clone()) && (!((&s.isgoal)).get(&v_t.clone()))))) {
        return Ok(None);
    }
    Ok(Some((v_t, )))
}

