fn enc_TSt(v: &TSt, out: &mut Vec<u8>) {
    codec::nat(match v {
        TSt::ABSENT => 0,
        TSt::WAITING => 1,
        TSt::READY => 2,
        TSt::RUNNING => 3,
        TSt::DONE => 4,
        TSt::FAILED => 5,
    }, out);
}

fn dec_TSt(r: &mut codec::Rd<'_>) -> Result<TSt, DecodeError> {
    match r.nat()? {
        0 => Ok(TSt::ABSENT),
        1 => Ok(TSt::WAITING),
        2 => Ok(TSt::READY),
        3 => Ok(TSt::RUNNING),
        4 => Ok(TSt::DONE),
        5 => Ok(TSt::FAILED),
        _ => Err(DecodeError("a constructor index")),
    }
}

/// The bytes of an entry (docs/spec.md §3.8.10).
pub fn encode(entry: &Entry, out: &mut Vec<u8>) {
    match entry {
        Entry::Event(Event::Define(a0, a1)) => {
            out.push(0);
            codec::nat(0, out);
            codec::nat(i128::from((a0).0), out);
            codec::len((a1).len(), out);
            for x2 in (a1).iter() {
                codec::nat(i128::from((x2).0), out);
            }
        }
        Entry::Event(Event::Failed(a0)) => {
            out.push(0);
            codec::nat(1, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Event(Event::Finished(a0)) => {
            out.push(0);
            codec::nat(2, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Event(Event::Goal(a0)) => {
            out.push(0);
            codec::nat(3, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Event(Event::Run) => {
            out.push(0);
            codec::nat(4, out);
        }
        Entry::Action(Action::Abandon(a0)) => {
            out.push(1);
            codec::nat(0, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Deliver(a0, a1)) => {
            out.push(1);
            codec::nat(1, out);
            codec::nat(i128::from((a0).0), out);
            codec::boolean(*(a1), out);
        }
        Entry::Action(Action::Finish) => {
            out.push(1);
            codec::nat(2, out);
        }
        Entry::Action(Action::Ready(a0)) => {
            out.push(1);
            codec::nat(3, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Start(a0)) => {
            out.push(1);
            codec::nat(4, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Tell(a0, a1)) => {
            out.push(1);
            codec::nat(5, out);
            codec::nat(i128::from((a0).0), out);
            codec::nat(i128::from((a1).0), out);
        }
    }
}

/// The entry of some bytes (§3.8.10).
pub fn decode(bytes: &[u8]) -> Result<Entry, DecodeError> {
    let mut r = codec::Rd { b: bytes, p: 0 };
    let r = &mut r;
    let side = r.byte()?;
    let code = r.nat()?;
    let e = match (side, code) {
        (0, 0) => Entry::Event(Event::Define(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?), { let n = r.len()?; let mut l = Vec::new(); for _ in 0..n { l.push(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?)); } l })),
        (0, 1) => Entry::Event(Event::Failed(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 2) => Entry::Event(Event::Finished(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 3) => Entry::Event(Event::Goal(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 4) => Entry::Event(Event::Run),
        (1, 0) => Entry::Action(Action::Abandon(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 1) => Entry::Action(Action::Deliver(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?), r.boolean()?)),
        (1, 2) => Entry::Action(Action::Finish),
        (1, 3) => Entry::Action(Action::Ready(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 4) => Entry::Action(Action::Start(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 5) => Entry::Action(Action::Tell(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?), Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        _ => return Err(DecodeError("a label")),
    };
    if !r.done() {
        return Err(DecodeError("trailing bytes"));
    }
    Ok(e)
}

