const OUTS: [fn(&mut S, &mut Vec<Action>) -> Result<bool, StepError>; 6] = [out0, out1, out2, out3, out4, out5];

/// The output summands' labels, in policy order (docs/spec.md §3.11.6).
pub const OUTPUT_LABELS: [&str; 6] = ["c_deliver", "c_tell", "c_abandon", "c_ready", "c_start", "c_finish"];

/// The index plus one, in [`OUTPUT_LABELS`], of the output summand fired last; 0:
/// none (docs/spec.md §3.11.6). Process-wide; written only with the feature `firing`.
#[cfg(feature = "firing")]
pub static FIRING: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

/// The label of the output summand fired last, read from any thread; `None`
/// without the feature `firing` or before the first fire (docs/spec.md §3.11.6).
pub fn firing() -> Option<&'static str> {
    #[cfg(feature = "firing")]
    {
        let i = FIRING.load(core::sync::atomic::Ordering::Relaxed);
        return usize::try_from(i).ok().and_then(|i| i.checked_sub(1)).and_then(|i| OUTPUT_LABELS.get(i)).copied();
    }
    #[cfg(not(feature = "firing"))]
    None
}

/// The output loop (docs/spec.md §3.8.3): the first enabled output in policy
/// order, until none is.
fn run_loop(s: &mut S, out: &mut Vec<Action>) -> Result<(), StepError> {
    let mut n: u32 = 0;
    loop {
        let mut fired = false;
        for f in OUTS {
            if f(s, out)? {
                fired = true;
                break;
            }
        }
        if !fired {
            return Ok(());
        }
        refresh(s)?;
        n = n.saturating_add(1);
        if n >= 1 << 24 {
            return Err(StepError::StepLimit);
        }
    }
}

fn state_bytes(s: &S, out: &mut Vec<u8>) {
    codec::nat(*(&s.w), out);
    codec::nat(*(&s.nt), out);
    codec::boolean(*(&s.begun), out);
    codec::boolean(*(&s.ended), out);
    codec::nat(*(&s.free), out);
    codec::nat(*(&s.pending), out);
    codec::nat(*(&s.settled), out);
    {
        let f = &s.st;
        enc_TSt(f.default_value(), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            enc_TSt(v, out);
        }
    }
    {
        let f = &s.kids;
        codec::len((f.default_value()).len(), out);
        for x27 in (f.default_value()).iter() {
            codec::nat(i128::from((x27).0), out);
        }
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::len((v).len(), out);
            for x28 in (v).iter() {
                codec::nat(i128::from((x28).0), out);
            }
        }
    }
    {
        let f = &s.isgoal;
        codec::boolean(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::boolean(*(v), out);
        }
    }
    {
        let f = &s.told;
        codec::boolean(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::boolean(*(v), out);
        }
    }
    {
        let f = &s.users;
        codec::len((f.default_value()).len(), out);
        for x29 in (f.default_value()).iter() {
            codec::nat(i128::from((x29).0), out);
        }
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::len((v).len(), out);
            for x30 in (v).iter() {
                codec::nat(i128::from((x30).0), out);
            }
        }
    }
    {
        let f = &s.missing;
        codec::nat(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::nat(*(v), out);
        }
    }
    {
        let f = &s.broken;
        codec::boolean(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::boolean(*(v), out);
        }
    }
    {
        let f = &s.todo;
        codec::len((f.default_value()).len(), out);
        for x31 in (f.default_value()).iter() {
            codec::nat(i128::from((x31).0), out);
        }
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::len((v).len(), out);
            for x32 in (v).iter() {
                codec::nat(i128::from((x32).0), out);
            }
        }
    }
}

/// The stepper of the refined Core (docs/spec.md §3.8.1, §3.8.2, §3.11.2).
#[derive(Debug, Clone)]
pub struct State {
    s: S,
}

impl State {
    pub fn new(config: Config, out: &mut Vec<Action>) -> Result<State, StepError> {
        State::new_with(config, out, |_| {})
    }

    /// The constructor with the initial state changed first, for tests that start
    /// from another initial state.
    #[doc(hidden)]
    pub fn new_with(config: Config, out: &mut Vec<Action>, f: impl FnOnce(&mut S)) -> Result<State, StepError> {
        let mut s = initial(&config)?;
        f(&mut s);
        stepper_init(&mut s)?;
        run_loop(&mut s, out)?;
        Ok(State { s })
    }

    pub fn step(&mut self, event: &Event, out: &mut Vec<Action>) -> Result<(), StepError> {
        let s = &mut self.s;
        match event {
            Event::Define(a0, a1) => {
                if let Some(env) = match_s0(s, a0, a1)? {
                    fire_s0(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Failed(a0) => {
                if let Some(env) = match_s4(s, a0)? {
                    fire_s4(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Finished(a0) => {
                if let Some(env) = match_s3(s, a0)? {
                    fire_s3(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Goal(a0) => {
                if let Some(env) = match_s1(s, a0)? {
                    fire_s1(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Run => {
                if let Some(env) = match_s2(s)? {
                    fire_s2(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
        }
        refresh(s)?;
        run_loop(s, out)
    }

    /// An estimate of the memory the state holds (§3.13.4).
    pub fn bytes(&self) -> usize {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b.len()
    }

    /// Every parameter's value, encoded as entries are (for comparing the backends).
    pub fn state_bytes(&self) -> Vec<u8> {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The members of an index in its order, for tests.
    pub fn index(&self, name: &str) -> Option<Vec<u32>> {
        match name {
            "due" => Some(self.s.ix_due.ordered()),
            "doomed" => Some(self.s.ix_doomed.ordered()),
            "telling" => Some(self.s.ix_telling.ordered()),
            "runnable" => Some(self.s.ix_runnable.ordered()),
            "queued" => Some(self.s.ix_queued.ordered()),
            _ => None,
        }
    }
}

